iteria": [\n        {\n          "id": "AC-ERR-001-1",\n          "description": "All errors return structured JSON",\n          "type": "functional"\n        },\n        {\n          "id": "AC-ERR-001-2",\n          "description": "500 errors do not leak stack traces",\n          "type": "functional"\n        },\n        {\n          "id": "AC-ERR-001-3",\n          "description": "Error codes are documented",\n          "type": "functional"\n        }\n      ]\n    },\n    "LOG-001": {\n      "title": "Application Logging",\n      "priority": "should",\n      "criteria": [\n        {\n          "id": "AC-LOG-001-1",\n          "description": "Logs include timestamp, severity, and context",\n          "type": "functional"\n        },\n        {\n          "id": "AC-LOG-001-2",\n          "description": "Logs are structured (JSON format)",\n          "type": "functional"\n        },\n        {\n          "id": "AC-LOG-001-3",\n          "description": "Sensitive data is redacted in logs",\n          "type": "functional"\n        }\n      ]\n    },\n    "PERF-001": {\n      "title": "Response Time",\n      "priority": "must",\n      "criteria": [\n        {\n          "id": "AC-PERF-001-1",\n          "description": "P95 latency < 200ms at 100 RPS",\n          "type": "non-functional"\n        },\n        {\n          "id": "AC-PERF-001-2",\n          "description": "P99 latency < 500ms at 100 RPS",\n          "type": "non-functional"\n        }\n      ]\n    },\n    "PERF-002": {\n      "title": "Throughput",\n      "priority": "should",\n      "criteria": [\n        {\n          "id": "AC-PERF-002-1",\n          "description": "System supports 1000 concurrent connections",\n          "type": "non-functional"\n        },\n        {\n          "id": "AC-PERF-002-2",\n          "description": "No degradation under sustained load",\n          "type": "non-functional"\n        }\n      ]\n    },\n    "SEC-001": {\n      "title": "Data Encryption",\n      "priority": "mu