a57f7048-2c85-4077-b4f8-52004c4dafb7	\N	0117b69b-3898-4ea4-83b0-8dc793c24d02	architecture-constraints.json	architecture	{\n  "constraints": [\n    {\n      "id": "CONST-no-direct-db-access",\n      "name": "No Direct DB Access",\n      "description": "Services must not directly access another service's database.",\n      "enforcement": "review"\n    },\n    {\n      "id": "CONST-api-versioning",\n      "name": "API Versioning",\n      "description": "All API endpoints must include version in URL path.",\n      "enforcement": "build_time"\n    },\n    {\n      "id": "CONST-auth-required",\n      "name": "Auth Required",\n      "description": "All API endpoints except health check require authentication.",\n      "enforcement": "build_time"\n    },\n    {\n      "id": "CONST-no-circular-dependencies",\n      "name": "No Circular Dependencies",\n      "description": "Service dependency graph must be acyclic.",\n      "enforcement": "build_time"\n    }\n  ],\n  "fitness_functions": [\n    {\n      "id": "FF-api-response-time",\n      "name": "API Response Time",\n      "description": "P95 response time for API endpoints",\n      "metric": "latency_p95_ms",\n      "threshold": "<= 200",\n      "current_value": null,\n      "status": "unknown"\n    },\n    {\n      "id": "FF-test-coverage",\n      "name": "Test Coverage",\n      "description": "Minimum code coverage",\n      "metric": "coverage_percent",\n      "threshold": ">= 80",\n      "current_value": null,\n      "status": "unknown"\n    },\n    {\n      "id": "FF-dependency-count",\n      "name": "Dependency Count",\n      "description": "Maximum dependencies per service",\n      "metric": "dependency_count",\n      "threshold": "<= 5",\n      "current_value": null,\n      "status": "unknown"\n    },\n    {\n      "id": "FF-service-count",\n      "name": "Service Count",\n      "description": "Maximum number of services",\n      "metric": "service_count",\n      "threshold": "<= 20",\n      "current_value": null,\n